package com.dorm.fourchess;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import java.util.concurrent.atomic.AtomicReference;
/** Actual card touch, skip, accessibility, rotation and no-reroll presentation checks. */
public final class SkillRevealProbe extends Instrumentation {
 private Bundle args;private MainActivity activity;private FourChessView board;private final StringBuilder log=new StringBuilder();
 @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 private void check(boolean b,String s){if(!b)throw new AssertionError(s);log.append("PASS ").append(s).append('\n');}
 private Object field(Object o,String s)throws Exception{Field f=o.getClass().getDeclaredField(s);f.setAccessible(true);return f.get(o);}
 private void main(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});waitForIdleSync();if(error.get()!=null)throw new AssertionError(error.get());}
 private interface Condition{boolean yes()throws Exception;}
 private void await(Condition condition,String label)throws Exception{for(int i=0;i<100;i++){if(condition.yes()){check(true,label);return;}SystemClock.sleep(50);}throw new AssertionError(label);}
 private void call(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(activity);}
 private SkillDrawView view()throws Exception{return (SkillDrawView)field(activity,"drawView");}
 private AlertDialog dialog()throws Exception{return (AlertDialog)field(activity,"drawDialog");}
 private void tap(View v,float x,float y){main(()->{long now=SystemClock.uptimeMillis();for(int a:new int[]{0,1}){MotionEvent e=MotionEvent.obtain(now,now,a,x,y,0);v.dispatchTouchEvent(e);e.recycle();}});}
 private void shot(String name)throws Exception{SystemClock.sleep(400);Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void layout()throws Exception{SkillDrawView v=view();RectF[] rects=(RectF[])field(v,"cards");float d=v.getResources().getDisplayMetrics().density;for(int i=0;i<4;i++){RectF r=rects[i];check(r.left>=0&&r.top>=0&&r.right<=v.getWidth()+1&&r.bottom<=v.getHeight()+1,"card fits content "+i);check(r.width()+1>=44*d&&r.height()+1>=44*d,"card touch at least44dp "+i);for(int j=0;j<i;j++)check(!RectF.intersects(r,rects[j]),"cards do not overlap "+i+"/"+j);}AlertDialog dialog=dialog();for(int id:new int[]{-1,-2,-3}){Button button=dialog.getButton(id);check(button.isShown()&&button.getWidth()>0&&button.getHeight()>=44*d,"native action available "+id);Rect out=new Rect();check(button.getGlobalVisibleRect(out)&&out.height()>=button.getHeight()-1,"native action not clipped "+id);}}
 private void runUi()throws Exception{
  activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));board=(FourChessView)field(activity,"board");boolean portrait=!"landscape".equals(args.getString("orientation","portrait"));main(()->activity.setRequestedOrientation(portrait?1:0));await(()->{View root=(View)field(activity,"screen");return activity.hasWindowFocus()&&(root.getHeight()>root.getWidth())==portrait;},"activity ready in requested orientation");
  android.widget.FrameLayout safeRoot=(android.widget.FrameLayout)field(activity,"screen");int[] originalInsets={safeRoot.getPaddingLeft(),safeRoot.getPaddingTop(),safeRoot.getPaddingRight(),safeRoot.getPaddingBottom()};int safe=Math.round(32*getTargetContext().getResources().getDisplayMetrics().density);
  main(()->safeRoot.setPadding(originalInsets[0],safe,originalInsets[2],originalInsets[3]));SystemClock.sleep(200);final Bitmap[] frame={null};main(()->{frame[0]=Bitmap.createBitmap(safeRoot.getWidth(),safeRoot.getHeight(),Bitmap.Config.ARGB_8888);safeRoot.draw(new Canvas(frame[0]));});int[] differences=new int[3];for(int k=0;k<3;k++){int x=safeRoot.getWidth()*(k+3)/8,a=frame[0].getPixel(x,safe-1),b=frame[0].getPixel(x,safe+1);differences[k]=Math.abs(Color.red(a)-Color.red(b))+Math.abs(Color.green(a)-Color.green(b))+Math.abs(Color.blue(a)-Color.blue(b));}frame[0].recycle();java.util.Arrays.sort(differences);check(differences[1]<18,"background stays continuous across simulated top safe inset");shot("reveal-safe-top.png");main(()->safeRoot.setPadding(originalInsets[0],originalInsets[1],originalInsets[2],originalInsets[3]));
  main(()->{try{ModeSelectView mode=(ModeSelectView)field(activity,"modePage");Method select=ModeSelectView.class.getDeclaredMethod("selectSkills",boolean.class);select.setAccessible(true);select.invoke(mode,true);Method start=MainActivity.class.getDeclaredMethod("startMatch",String[].class);start.setAccessible(true);start.invoke(activity,(Object)new String[]{"红棋友","绿棋友","蓝棋友","金棋友"});}catch(Exception e){throw new RuntimeException(e);}});
  await(()->dialog()!=null&&view().getWidth()>0&&view().hasWindowFocus(),"opening reveal automatically appears");layout();for(int i=0;i<4;i++)check(((int[])field(view(),"charges"))[i]==board.skillRemaining(0,board.skillHand(0)[i]),"draw shows actual charges "+i);String opening=board.exportState();SkillDrawView v=view();AlertDialog shown=dialog();check(!shown.getButton(-1).isEnabled(),"enter disabled before reveal");
  for(int i=1;i<=4;i++){String desc=v.getAccessibilityNodeProvider().createAccessibilityNodeInfo(i).getContentDescription().toString();check(desc.contains("点击揭晓")&&!desc.contains(SkillRules.name(board.skillHand(0)[i-1])),"card back accessibility conceals skill "+i);}
  shot("reveal-backs.png");RectF first=((RectF[])field(v,"cards"))[0];tap(v,first.centerX(),first.centerY());await(()->v.getAccessibilityNodeProvider().createAccessibilityNodeInfo(1).getContentDescription().toString().contains(SkillRules.name(board.skillHand(0)[0])),"real touch flips first fixed card");check(!v.allRevealed()&&opening.equals(board.exportState()),"single flip does not reroll or spend skill");
  main(()->shown.getButton(-3).performClick());await(v::allRevealed,"staggered reveal completes four cards");await(()->shown.getButton(-1).isEnabled(),"enter enabled after reveal");check(opening.equals(board.exportState())&&board.undoCount()==0,"all reveal changes no board/charge/history");shot("reveal-results.png");
  main(()->activity.setRequestedOrientation(portrait?0:1));await(()->{View root=(View)field(activity,"screen");return (root.getHeight()>root.getWidth())!=portrait;},"rotate with reveal open");SystemClock.sleep(250);layout();check(view()==v&&opening.equals(board.exportState()),"rotation preserves same reveal and hand");shot("reveal-rotated.png");main(()->shown.getButton(-1).performClick());await(()->dialog()==null,"enter returns to live match");
  SkillRackView rack=(SkillRackView)field(activity,"skillRack");float density=rack.getResources().getDisplayMetrics().density;check(rack.isShown()&&rack.getChildCount()==4,"four shortcuts shown in live match");for(int i=0;i<4;i++){View tile=rack.getChildAt(i);Rect bounds=new Rect();check(tile.getWidth()+1>=44*density&&tile.getHeight()+1>=44*density,"skill shortcut 44dp "+i);check(tile.getGlobalVisibleRect(bounds)&&bounds.width()>=tile.getWidth()-1&&bounds.height()>=tile.getHeight()-1,"shortcut not clipped "+i);check(((Button)tile).getText().toString().contains(SkillRules.name(board.skillHand(0)[i])),"shortcut matches actual hand "+i);}
  boolean livePortrait=((View)field(activity,"screen")).getHeight()>((View)field(activity,"screen")).getWidth();if(livePortrait){check(rack.getChildAt(0).getTop()==rack.getChildAt(1).getTop()&&rack.getChildAt(2).getTop()>rack.getChildAt(0).getTop(),"portrait skills form two columns and two rows");}
  for(int i=0;i<4;i++){View tile=rack.getChildAt(i);int id=board.skillHand(0)[i];check((Integer)field(tile,"remaining")==board.skillRemaining(0,id),"badge binds actual remaining count "+i);check(!tile.willNotDraw(),"skill title drawing enabled "+i);check(((Button)tile).getMaxLines()==1,"skill title remains single line "+i);check(tile.isEnabled()==board.skillAvailable(id),"availability matches real board targets "+i);}
  String rackState=board.exportState();main(()->{try{Method detail=MainActivity.class.getDeclaredMethod("showSkillCard",int.class);detail.setAccessible(true);detail.invoke(activity,0);}catch(Exception e){throw new RuntimeException(e);}});check(field(activity,"skillCardDialog")!=null,"shortcut opens skill details");main(()->((AlertDialog)quiet("skillCardDialog")).getButton(-2).performClick());check(rackState.equals(board.exportState()),"reading shortcut details never spends skill");SystemClock.sleep(400);shot("reveal-live.png");
  main(()->{try{call("showSkillOptions");}catch(Exception e){throw new RuntimeException(e);}});check(field(activity,"skillDialog")!=null&&dialog()==null,"reopening skills uses hand menu without repeating draw");main(()->((AlertDialog)quiet("skillDialog")).dismiss());
  main(()->check(board.tryNetworkMove(0,5,15,5,14),"normal move still commits after reveal"));await(()->dialog()!=null,"next same-screen player gets own reveal");int[] green=board.skillHand(1);check(java.util.Arrays.equals(green,(int[])field(view(),"hand")),"second player sees correct four cards");String beforeSkip=board.exportState();AlertDialog second=dialog();SkillDrawView secondView=view();main(()->second.getButton(-2).performClick());check(secondView.allRevealed()&&second.getButton(-1).isEnabled(),"skip immediately reveals and enables entry");check(beforeSkip.equals(board.exportState()),"skip does not redeal or cast");main(()->second.getButton(-1).performClick());main(()->{try{Method undo=MainActivity.class.getDeclaredMethod("performUndo",int.class);undo.setAccessible(true);undo.invoke(activity,1);}catch(Exception e){throw new RuntimeException(e);}});SystemClock.sleep(200);check(opening.equals(board.exportState())&&dialog()==null,"undo restores exact hand without replaying draw");
  String[] cycle=opening.split("\\|",2),cycleHeader=cycle[0].split(",");cycleHeader[0]="3";cycleHeader[44]="9";cycleHeader[45]="7";String prior=String.join(",",cycleHeader)+"|"+cycle[1];
  main(()->{java.util.Arrays.fill((boolean[])quiet("handRevealed"),true);board.importState(prior);});SystemClock.sleep(200);
  main(()->check(board.tryNetworkMove(3,18,6,16,7),"UI commits tenth full round"));await(()->dialog()!=null,"periodic draw opens automatically");check(board.skillGeneration()==1&&java.util.Arrays.equals(board.skillHand(0),(int[])field(view(),"hand")),"new draw uses refreshed real hand");main(()->((AlertDialog)quiet("drawDialog")).getButton(-2).performClick());main(()->((AlertDialog)quiet("drawDialog")).getButton(-1).performClick());await(()->dialog()==null,"refreshed draw returns to match");
  for(int i=0;i<4;i++)check((Integer)field(rack.getChildAt(i),"remaining")==board.skillRemaining(0,board.skillHand(0)[i]),"refresh updates badge "+i);
  main(()->check(board.undoSteps(1),"UI undo across deal succeeds"));await(()->dialog()!=null,"undo presents restored generation hand");check(prior.equals(board.exportState())&&java.util.Arrays.equals(board.skillHand(3),(int[])field(view(),"hand")),"undo restores actual previous hand and round");main(()->((AlertDialog)quiet("drawDialog")).getButton(-2).performClick());main(()->((AlertDialog)quiet("drawDialog")).getButton(-1).performClick());
  main(()->{try{call("exitToLobby");}catch(Exception e){throw new RuntimeException(e);}});check(dialog()==null,"exit cleans up presentation");log.append("REVEAL COMPLETE\n");
 }
 private Object quiet(String name){try{return field(activity,name);}catch(Exception e){throw new RuntimeException(e);}}
 @Override public void onStart(){Bundle result=new Bundle();try{runUi();result.putString("stream",log.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream",log+"FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
